import { HTTPError } from "../error.ts";
import type { ErrorInput } from "../error.ts";
import { getStatusText } from "./internal/status-text.ts";

export interface ProblemInput<DataT = unknown> extends ErrorInput<DataT> {
  /** Reference URI identifying the problem type. Defaults to `"about:blank"`. */
  type?: string;
  /** Reference URI identifying this occurrence of the problem. */
  instance?: string;
}

/**
 * Create an {@link HTTPError} whose response follows RFC 9457 (Problem Details for HTTP APIs).
 *
 * The response uses the `application/problem+json` content type.
 */
export function problem<DataT = unknown>(input: ProblemInput<DataT>): HTTPError<DataT> {
  const { type, instance, ...rest } = input;
  const error = new HTTPError<DataT>(rest);
  Object.defineProperty(error, "~problem", {
    value: (e: HTTPError) => toProblemBody(e, { type, instance, message: input.message }),
  });
  return error;
}

// --- internal ---

const standardMembers = new Set(["type", "title", "status", "detail", "instance"]);

function toProblemBody(
  error: HTTPError,
  input: { type?: unknown; instance?: unknown; message?: unknown },
): Record<string, unknown> {
  const unhandled = error.unhandled === true;
  const { type, instance, message } = input;
  const extensions = unhandled
    ? undefined
    : [
        ...(error.data === undefined ? [] : [["data", error.data] as const]),
        ...Object.entries(error.body || {}),
      ].filter(([key], index, all) => {
        // Standard members win; `data` wins over `body`
        return !standardMembers.has(key) && all.findIndex(([k]) => k === key) === index;
      });
  return Object.fromEntries([
    ["type", typeof type === "string" ? type : "about:blank"],
    ["title", error.statusText || getStatusText(error.status)],
    ["status", error.status],
    ["detail", !unhandled && typeof message === "string" && message ? message : undefined],
    ["instance", typeof instance === "string" ? instance : undefined],
    ...(extensions || []),
  ]);
}

